/* generated child CSS: 03-cta/cta.btn-base/block.css */
/* lab-ui block · cta.btn-base
   Depends: 00-tokens/tokens.css (--radius-pill, --font-family,
   --transition-duration). Shared geometry + .btn-star base for every
   CTA variant. Variant blocks (cta.btn-primary-ring,
   cta.btn-secondary-filled) layer their own ::before/::after, halo
   shadows and color tokens on top. */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-width: 13rem;
  height: 3.25rem;
  padding: 0 1.625rem;
  border-radius: var(--radius-pill);
  font-family: var(--font-family);
  font-weight: 500;
  font-size: 1rem;
  white-space: nowrap;
  position: relative;
  text-decoration: none;
  cursor: pointer;
  border: 0;
  transition: box-shadow var(--transition-duration) ease,
              transform var(--transition-duration) ease;
}

.btn-star {
  flex-shrink: 0;
  transition: transform var(--transition-duration) cubic-bezier(.4, 0, .2, 1);
}


/* generated child CSS: 12-decorative/effect.hover-rise/block.css */
/* ============================================================
   lab-ui block · effect.hover-rise
   ----------------------------------------------------------------
   Brand interaction primitive — standard CTA halo + inner bottom-glow
   that fades in on :hover. Applied via CSS, no markup.

   ## Where it auto-applies (brand primitives)
   - .btn-primary-ring          (cta.btn-primary-ring)
   - .btn-secondary-filled      (cta.btn-secondary-filled)
   - .nav-link, .nav-trigger    (header.default nav items)
   - .locale-trigger            (language.locale-dropdown)
   - .bc-link                   (header.default breadcrumb)

   ## Opt-in for custom elements
   - [data-fx="rise"]

   ## Tint
   Default uses --cta-accent (which is --color-cyan by default and
   re-themed via [data-theme="..."] overlays). Override per element
   via --fx-rise-color: <color>.

   ## Implementation
   Each target element gets a ::after pseudo with the canonical
   bottom-centered radial glow used by current CTA blocks, plus an
   outer hover halo via box-shadow. No external image asset.

   ## Stacking
   Container must be position:relative (or rely on the host block
   making itself relative — all brand-primitive blocks already do).
   The ::after is z-index:1 with pointer-events:none so it never
   blocks interaction.
   ============================================================ */

:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
)::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 0;
  transform: translateX(-50%);
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
  border-radius: inherit;
  opacity: 0;
  transition: opacity var(--transition-duration, 0.25s) ease;

  /* Canonical inner glow: same bottom-centered radial used by
     cta.btn-primary-ring and cta.btn-secondary-filled. */
  background: radial-gradient(
    ellipse 58% 78% at 50% 100%,
    var(--fx-rise-color, var(--cta-accent, #6BEAF9)) 0%,
    transparent 60%
  );
  mix-blend-mode: normal;
  filter: none;
}

/* Activate on hover + on keyboard focus-visible (a11y). */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
):is(:hover, :focus-visible)::after {
  opacity: 0.48;
}

/* Brand-primitive base — they all need to be relative for the
   ::after to anchor inside. Each block also sets this in its own
   block.css, but we re-declare here so the effect works even when
   only this CSS is imported. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
) {
  position: relative;
  overflow: hidden;
  transition:
    box-shadow var(--transition-duration, 0.25s) ease,
    transform var(--transition-duration, 0.25s) ease;
}

/* Outer halo — two intensities so the same effect doesn't look
   aggressive on a 32 px nav link AND on a 52 px pill button.

   Strong (default): pills, cards, opt-in via [data-fx="rise"].
   Soft: header chrome — nav links, dropdown triggers, breadcrumb,
   locale chip. Override per element via --fx-rise-color. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  [data-fx="rise"]
):is(:hover, :focus-visible) {
  box-shadow: 0 0 32px -4px var(--fx-rise-color, var(--cta-accent, #6BEAF9));
}

:where(
  .nav-link,
  .nav-trigger,
  .locale-trigger
):is(:hover, :focus-visible) {
  box-shadow: 0 0 18px -6px var(--fx-rise-color, var(--cta-accent, #6BEAF9));
}

/* Keyboard-only focus ring (a11y). Distinct from the hover halo so that
   keyboard navigation is unambiguously visible — sighted hover users do
   not get the ring, only the soft glow. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
):focus-visible {
  outline: 2px solid var(--fx-rise-color, var(--cta-accent, #6BEAF9));
  outline-offset: 2px;
}

/* The hover-rise must stay BEHIND the element's own contents.
   We use overflow:hidden + ::after with z-index 1 — content sits
   at z-index 2. Brand primitives bump their direct children to
   z-index 2 here so we don't have to touch every block.css. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
) > * {
  position: relative;
  z-index: 2;
}

/* Reduced-motion: keep the effect but kill the transition so it
   appears instantly on hover with no animation. */
@media (prefers-reduced-motion: reduce) {
  :where(
    .btn-primary-ring,
    .btn-secondary-filled,
    .nav-link,
    .nav-trigger,
    .locale-trigger,
    .bc-link,
    [data-fx="rise"]
  )::after {
    transition: none;
  }
}


/* generated child CSS: 03-cta/cta.btn-primary-ring/block.css */
/* lab-ui block · cta.btn-primary-ring
   Depends: 00-tokens/tokens.css (--color-black, --radius-pill,
   --font-family, --gradient-cta-ring, --transition-duration,
   --cta-accent, --cta-accent-soft) + 03-cta/cta.btn-base (.btn, .btn-star). */

.btn-primary {
  background: var(--button-primary-bg, transparent);
  color: var(--button-primary-color, var(--color-black));
}

.btn-primary-ring {
  position: relative;
  overflow: hidden;
}

.btn-primary-ring::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1.5px;
  background: var(--gradient-cta-ring);
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
          mask-composite: exclude;
  pointer-events: none;
  z-index: 3;                          /* above hover-rise ::after */
  transition: background var(--transition-duration) ease;
}

/* On hover the rainbow ring rotates direction 249° → 264° (matches
   live the platform .button-primary:hover::before). */
.btn-primary-ring:hover::before {
  background: linear-gradient(
    264.85deg,
    rgba(239, 92, 255, 0)   -6.54%,
    #FFA72C                 24.73%,
    #6BEDF9                 70.73%,
    rgba(107, 237, 249, 0) 113.1%
  );
}

/* Outer brand glow on hover — tighter than sw's stock 41 px so it
   reads as a halo hugging the pill, not a rectangular smear behind
   it (matches the production reference). Tinted by --cta-accent so
   each vertical paints its own color. */
.btn-primary-ring:hover {
  box-shadow: 0 0 32px -4px var(--cta-accent, #6BEAF9);
}

/* Match cta.btn-secondary-filled's hover affordance: a tighter
   bottom-centered radial glow that fades in, instead of the shared
   effect.hover-rise strip. The ring remains on ::before above it.
   Keep normal blending so the glow stays visible on white buttons. */
.btn-primary-ring::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: none;
  border-radius: inherit;
  pointer-events: none;
  z-index: 1;
  background: radial-gradient(
    ellipse 58% 78% at 50% 100%,
    var(--cta-accent, #6BEAF9) 0%,
    transparent 60%
  );
  opacity: 0;
  filter: none;
  background-blend-mode: normal;
  mix-blend-mode: normal;
  transition: opacity var(--transition-duration) ease;
}

.btn-primary-ring:hover::after {
  opacity: 0.48;
}

.btn-primary-ring:hover .btn-star {
  transform: rotate(180deg);
}


/* generated child CSS: 04-language/language.locale-dropdown/block.css */
/* lab-ui block · language.locale-dropdown
   Depends: 00-tokens/tokens.css (--header-bg, --color-heading, --locale-selector-bg,
   --transition-duration, --color-cyan). */

.locale-selector {
  position: relative;
  isolation: isolate;
  font-family: var(--font-family);
}

.locale-trigger {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding-inline: 15px;
  height: 42px;
  border: 1px solid var(--card-border, transparent);
  border-radius: 10px;
  background-color: var(--header-bg, var(--color-light-card-bg));
  color: var(--color-heading);
  font-size: 1rem;
  font-weight: 400;
  letter-spacing: -0.01em;
  cursor: pointer;
  white-space: nowrap;
  min-width: 180px;
  transition: border-radius 0.2s ease;
}

.locale-trigger-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

.locale-selector.is-open .locale-trigger {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

/* Opt out of effect.hover-rise's halo + inner radial — the locale chip
   is a quiet chrome element. Keyboard focus outline from effect.hover-rise
   is preserved for a11y. */
.locale-trigger::after { display: none; }
.locale-trigger:hover,
.locale-trigger:focus-visible {
  box-shadow: none;
}

.locale-chevron {
  flex-shrink: 0;
  transition: transform var(--transition-duration) cubic-bezier(0.4, 0, 0.2, 1);
}

.locale-selector.is-open .locale-chevron {
  transform: rotate(180deg);
}

.locale-dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  min-width: 100%;
  background-color: var(--locale-selector-bg, var(--color-gray-bg));
  border: 1px solid var(--card-border, rgba(0, 0, 0, 0.05));
  border-top: 0;
  border-bottom-right-radius: 1.25rem;
  border-bottom-left-radius: 1.25rem;
  overflow: hidden;
  z-index: 50;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(8px);
  transition:
    opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1),
    transform 0.25s cubic-bezier(0.4, 0, 0.2, 1),
    visibility 0.25s;
}

.locale-selector.is-open .locale-dropdown {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateY(0);
}

.locale-list {
  list-style: none;
  margin: 0;
  padding: 0.5rem 0;
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  max-height: 304px;
  overflow-y: auto;
}

.locale-item {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.625rem 1rem;
  color: var(--color-heading);
  font-size: 1rem;
  font-weight: 400;
  cursor: pointer;
  white-space: nowrap;
  position: relative;
  opacity: 0;
  transform: translateX(-4px);
  transition:
    opacity 0.2s ease,
    transform 0.2s ease,
    background-color var(--transition-duration) ease;
}

.locale-selector.is-open .locale-item {
  opacity: 1;
  transform: translateX(0);
}

.locale-selector.is-open .locale-item:nth-child(1) { transition-delay: 0.04s; }
.locale-selector.is-open .locale-item:nth-child(2) { transition-delay: 0.07s; }
.locale-selector.is-open .locale-item:nth-child(3) { transition-delay: 0.10s; }
.locale-selector.is-open .locale-item:nth-child(4) { transition-delay: 0.13s; }
.locale-selector.is-open .locale-item:nth-child(5) { transition-delay: 0.16s; }

.locale-item:hover {
  background-color: rgba(0, 0, 0, 0.04);
}

.locale-item.is-active {
  background-color: rgba(107, 192, 249, 0.1);
}

.locale-item-label {
  flex: 1;
}

.locale-item-code {
  display: none;
}

.locale-check {
  width: 0.875rem;
  height: 0.875rem;
  flex-shrink: 0;
  color: var(--color-cyan, #6BC0F9);
  opacity: 0;
  transform: scale(0.6);
  transition:
    opacity 0.2s ease,
    transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.locale-item.is-active .locale-check {
  opacity: 1;
  transform: scale(1);
}

@media (max-width: 600px) {
  .locale-selector {
    display: inline-block;
  }
}

.locale-selector--mobile .locale-trigger {
  width: 2.625rem;
  min-width: 0;
  height: 2.625rem;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: rgba(27, 29, 37, 0.045);
}

.locale-selector--mobile.is-open .locale-trigger {
  border-radius: 999px;
}

.locale-selector--mobile .locale-trigger::before {
  content: attr(data-short-code);
  display: block;
  font-family: var(--font-mono, monospace);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0;
  line-height: 1;
}

.locale-selector--mobile .locale-trigger:not([data-short-code])::before,
.locale-selector--mobile .locale-trigger[data-short-code=""]::before {
  content: "EN";
}

.locale-selector--mobile .locale-trigger-left {
  display: none;
}

.locale-selector--mobile .locale-dropdown {
  top: calc(100% + 0.375rem);
  left: auto;
  right: 0;
  min-width: 3rem;
  border: 1px solid var(--card-border, rgba(0, 0, 0, 0.05));
  border-radius: 1rem;
  background: var(--locale-selector-bg, var(--color-gray-bg));
}

.locale-selector--mobile .locale-list {
  align-items: center;
  padding: 0.375rem;
  gap: 0.25rem;
}

.locale-selector--mobile .locale-item {
  width: 2.25rem;
  height: 2.25rem;
  justify-content: center;
  padding: 0;
  border-radius: 0.75rem;
}

.locale-selector--mobile .locale-item::before {
  content: attr(data-short-code);
  color: var(--color-heading);
  font-family: var(--font-mono, monospace);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0;
  line-height: 1;
}

.locale-selector--mobile .locale-item:has(.locale-item-code)::before {
  display: none;
}

.locale-selector--mobile .locale-item-label,
.locale-selector--mobile .locale-check {
  display: none;
}

.locale-selector--mobile .locale-item-code {
  display: block;
  color: var(--color-heading);
  font-family: var(--font-mono, monospace);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0;
  line-height: 1;
}

@media (max-width: 600px) {
  .locale-trigger {
    width: 2.625rem;
    min-width: 0;
    height: 2.625rem;
    justify-content: center;
    padding: 0;
    border: 0;
    border-radius: 999px;
    background: rgba(27, 29, 37, 0.045);
  }

  .locale-selector.is-open .locale-trigger {
    border-radius: 999px;
  }

  .locale-trigger::before {
    content: attr(data-short-code);
    display: block;
    font-family: var(--font-mono, monospace);
    font-size: 0.6875rem;
    font-weight: 500;
    letter-spacing: 0;
    line-height: 1;
  }

  .locale-trigger:not([data-short-code])::before,
  .locale-trigger[data-short-code=""]::before {
    content: "EN";
  }

  .locale-trigger-left {
    display: none;
  }

  .locale-dropdown {
    top: calc(100% + 0.375rem);
    left: auto;
    right: 0;
    min-width: 3rem;
    border: 1px solid var(--card-border, rgba(0, 0, 0, 0.05));
    border-radius: 1rem;
    background: var(--locale-selector-bg, var(--color-gray-bg));
  }

  .locale-list {
    align-items: center;
    padding: 0.375rem;
    gap: 0.25rem;
  }

  .locale-item {
    width: 2.25rem;
    height: 2.25rem;
    justify-content: center;
    padding: 0;
    border-radius: 0.75rem;
  }

  .locale-item::before {
    content: attr(data-short-code);
    color: var(--color-heading);
    font-family: var(--font-mono, monospace);
    font-size: 0.6875rem;
    font-weight: 500;
    letter-spacing: 0;
    line-height: 1;
  }

  .locale-item:has(.locale-item-code)::before {
    display: none;
  }

  .locale-item-label,
  .locale-check {
    display: none;
  }

  .locale-item-code {
    display: block;
    color: var(--color-heading);
    font-family: var(--font-mono, monospace);
    font-size: 0.6875rem;
    font-weight: 500;
    letter-spacing: 0;
    line-height: 1;
  }
}


/* generated child CSS: 01-header/header.default/block.css */
/* lab-ui block · header.default
   Depends: 00-tokens/tokens.css + 03-cta/cta.btn-primary-ring/block.css
   + 04-language/language.locale-dropdown/block.css. Light theme.

   Multi-level nav model:
     .nav-item[data-kind="link"]      — plain anchor (no panel)
     .nav-item[data-kind="dropdown"]  — trigger + .nav-panel--list  (single-column)
     .nav-item[data-kind="mega"]      — trigger + .nav-panel--mega  (multi-column)

   Desktop panels open on :hover + :focus-within and on [data-open="true"]
   (the latter is for click/tap toggling via block.js). Below 1024px,
   the burger reveals a full-width menu and nested panel links are shown
   inline instead of as accordions. */

.header-host {
  position: sticky;
  top: 0;
  z-index: 40;
}

.header-host .header--default {
  position: relative;
  top: auto;
}

.header--default {
  position: sticky;
  top: 0;
  z-index: 40;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(var(--backdrop-blur-header, 1.25rem));
  -webkit-backdrop-filter: blur(var(--backdrop-blur-header, 1.25rem));
  border-bottom-left-radius: 2rem;
  border-bottom-right-radius: 2rem;
  box-shadow: 0 18px 46px -34px rgba(27, 29, 37, 0.42);
  transition: background-color var(--transition-duration) ease,
              box-shadow var(--transition-duration) ease;
}

.header--default .container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

.header--default .header-inner {
  position: relative;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 26px;
  min-height: 4.375rem;
  font-family: var(--font-family);
}

.header--default .header-logo {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--color-heading);
  text-decoration: none;
}
.header--default .header-logo svg {
  width: 20px;
  height: 20px;
}
.header--default .header-logo-text {
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -0.018em;
}

/* ─── Nav (unified) ─── */
.header-nav {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  justify-self: center;
}

.nav-item { position: relative; }

.nav-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: 999px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-heading);
  text-decoration: none;
  transition: background 0.2s ease, color 0.2s ease;
  background: transparent;
  border: 0;
  cursor: pointer;
  font-family: inherit;
  line-height: 1;
}
.nav-link:hover,
.nav-item:hover > .nav-link,
.nav-item[data-open="true"] > .nav-link {
  background: rgba(27, 29, 37, 0.045);
}

.nav-chev { transition: transform 0.2s ease; }
.nav-item:hover .nav-chev,
.nav-item:focus-within .nav-chev,
.nav-item[data-open="true"] .nav-chev { transform: rotate(180deg); }

/* ─── Panels (shared base) ─── */
.nav-panel {
  position: absolute;
  top: calc(100% + 8px);
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid rgba(27, 29, 37, 0.08);
  border-radius: 18px;
  box-shadow: 0 24px 60px -26px rgba(27, 29, 37, 0.34);
  backdrop-filter: blur(var(--backdrop-blur-panel, 18px));
  -webkit-backdrop-filter: blur(var(--backdrop-blur-panel, 18px));
  opacity: 0;
  pointer-events: none;
  transform: translateY(-4px);
  transition: opacity 0.18s ease, transform 0.18s ease;
  z-index: 50;
}

/* Invisible hover-bridge that spans the 8 px gap between the trigger
   and the panel. Without it, mouse moving from trigger down into the
   panel leaves nav-item's bounding box mid-gap, :hover drops, panel
   closes before the mouse arrives. The bridge is a child of .nav-panel
   (so it inherits the parent's pointer-events:auto when the panel is
   open) and extends UP from the panel's top edge by 10 px so it covers
   the visual gap. Stays full panel width so diagonal mouse paths still
   land in it. */
.nav-panel::before {
  content: "";
  position: absolute;
  top: -10px;
  left: 0;
  right: 0;
  height: 10px;
  /* background: rgba(255,0,0,0.15);  ← uncomment to debug */
}

.nav-item:hover > .nav-panel,
.nav-item:focus-within > .nav-panel,
.nav-item[data-open="true"] > .nav-panel {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

/* ─── List panel (dropdown) ─── */
.nav-panel--list {
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  min-width: 220px;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  list-style: none;
  margin: 0;
}
.nav-item:hover > .nav-panel--list,
.nav-item:focus-within > .nav-panel--list,
.nav-item[data-open="true"] > .nav-panel--list {
  transform: translateX(-50%) translateY(0);
}
.nav-list-link {
  display: block;
  padding: 10px 14px;
  border-radius: 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-heading);
  text-decoration: none;
  transition: background 0.15s ease;
}
.nav-list-link:hover { background: rgba(27, 29, 37, 0.045); }

/* ─── Mega panel ─── */
.nav-panel--mega {
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  width: max-content;
  max-width: min(680px, 92vw);
  padding: 14px;
  display: grid;
  grid-template-columns: repeat(2, minmax(176px, 1fr));
  gap: 12px 16px;
}
.nav-item:hover > .nav-panel--mega,
.nav-item:focus-within > .nav-panel--mega,
.nav-item[data-open="true"] > .nav-panel--mega {
  transform: translateX(-50%) translateY(0);
}
.nav-mega-col { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.nav-mega-title {
  margin: 0 0 5px;
  font-family: var(--font-mono);
  font-size: 0.625rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-gray-blue);
  font-weight: 500;
}
.nav-mega-link {
  display: block;
  padding: 8px 10px;
  border-radius: 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-heading);
  text-decoration: none;
  transition: background 0.15s ease;
}
.nav-mega-link:hover { background: rgba(27, 29, 37, 0.045); }

/* Hide empty mega columns / links via block.js (sets [hidden]) */
.nav-panel [hidden] { display: none !important; }

/* ─── Optional Breadcrumb Chip ───
   Breadcrumb is owned by header.default. It hangs from the sticky
   header's bottom edge inside the same page/header host. */
.bc-chip {
  position: absolute;
  top: 4.375rem;
  left: max(
    var(--container-padding-x),
    calc((100vw - (var(--container-width) + var(--container-padding-x) * 2)) / 2 + var(--container-padding-x))
  );
  z-index: 30;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  height: 30px;
  padding: 0 12px;
  border-radius: 0 0 14px 14px;
  font-family: var(--font-family);
  font-size: 12px;
  color: var(--color-text);
  background: linear-gradient(
    188.96deg,
    rgba(255, 255, 255, 0.85) 15.85%,
    rgba(224, 224, 224, 0.17) 92.84%
  );
  backdrop-filter: blur(3.125rem);
  -webkit-backdrop-filter: blur(3.125rem);
  border: 1px solid rgba(0, 0, 0, 0.04);
  border-top: 0;
  box-shadow: 0 6px 16px -12px rgba(0, 0, 0, 0.18);
  white-space: nowrap;
  min-width: 0;
  max-width: min(
    calc(var(--container-width) - var(--container-padding-x) * 2),
    calc(100vw - var(--container-padding-x) * 2)
  );
}

.bc-chip .bc-link {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--color-text);
  text-decoration: none;
  transition: color 0.15s ease;
}

.bc-chip .bc-link:hover { color: var(--color-heading); }

.bc-chip .bc-root {
  font-weight: 500;
  color: var(--color-heading);
}

.bc-chip .bc-sep {
  color: var(--color-gray-blue);
  font-family: var(--font-mono);
  font-size: 10px;
}

.bc-chip .bc-current {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--color-heading);
  font-weight: 500;
}

.bc-chip [data-mid][hidden],
.bc-chip [data-sep-for][hidden] {
  display: none !important;
}

.header-host.is-open .bc-chip,
body.is-open .bc-chip {
  display: none;
  opacity: 0;
  pointer-events: none;
}

/* ─── Actions ─── */
.header-actions {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.header-cta { min-width: auto; height: 2.625rem; padding: 0 1.2rem; font-size: 0.9375rem; }

/* ─── Burger ─── */
.burger {
  display: none;
  flex-direction: column;
  gap: 4px;
  width: 2.625rem;
  height: 2.625rem;
  align-items: center;
  justify-content: center;
